 Here is a C++ program that meets your requirements:

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n <= 0) {
        throw invalid_argument("Number of sequence elements must be positive.");
    }
    if (!isdigit(a + '_' - '0') || !isdigit(a + '_' - '1') || a < 0 || b < 0) {
        throw invalid_argument("Invalid initial values. Both must be non-negative integers.");
    }

    if (n == 1) {
        return a;
    }
    if (n == 2) {
        return a; // First two initial values are printed in the call below
    }
    return fibonacci(n - 1, b, a + b);
}

void printFibonacciSequence(int n, int a, int b) {
    try {
        int next = fibonacci(n, a, b);
        cout << a << ", ";
        printFibonacciSequence(n - 1, b, next);
    } catch (const invalid_argument& e) {
        cerr << "Error: " << e.what() << endl;
    }
}

int main() {
    int numElements, first, second;

    cout << "Enter the first two numbers of the Fibonacci sequence: ";
    cin >> first >> second;
    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    printFibonacciSequence(numElements, first, second);

    return 0;
}
```

